const input = $input.first().json ?? {};
const product = input.product ?? {};

const images = Array.isArray(product.images) ? product.images : [];
const variants = Array.isArray(product.variants) ? product.variants : [];

function imageUrlById(imageId) {
  if (!imageId) return null;
  const found = images.find((img) => img.id === imageId);
  return found ? found.src : null;
}

const featured =
  (product.image && product.image.src) ? product.image.src :
  (images[0] ? images[0].src : null);

const variantImages = {};
for (const variant of variants) {
  const byId = imageUrlById(variant.image_id);
  variantImages[variant.id] = byId || featured || null;
}

return [{
  json: {
    main_image_url: featured,
    variant_images: variantImages
  }
}];

